async function registerView() {
	const base = document.querySelector("meta[name=\"waterrules-site-api-base\"]")?.content || "/api/";
	const url = new URL("page-views", new URL(base, document.baseURI));
	if (!["http:", "https:"].includes(url.protocol)) throw Error("A server is needed to count page views.");
	const response = await fetch(url, {
		method: "POST",
		headers: { Accept: "application/json" },
		credentials: "same-origin",
		signal: AbortSignal.timeout(15e3)
	});
	if (!response.ok) throw Error("Page views unavailable");
	const text = await response.text();
	if (/^\s*</.test(text)) throw Error("Page views unavailable");
	const body = JSON.parse(text);
	if (!Number.isSafeInteger(body.views) || body.views < 0) throw Error("Invalid page-view count");
	return body;
}
