	if (/which rules|rules apply|what rules/.test(q.toLowerCase()) && population > 0) return all.filter((p) => p.kind === "rules" && (p.page === 10 || p.page === 11)).slice(0, 5);
	const ts = tokens(q);
	const modules = supply === "small" ? [
		"S1.",
		"T1.",
		"D1."
	] : supply === "medium" ? [
		"S2.",
		"T2.",
		"D2."
	] : supply === "large" ? [
		"S3.",
		"T3.",
		"D3."
	] : supply === "very-small" ? ["VSC."] : [];
	return all.map((p) => {
		const body = p.text.toLowerCase();
		let score = ts.reduce((n, t) => n + ([t, ...aliases[t] || []].some((v) => body.includes(v)) ? 2 : 0) + (body.includes(t) ? 1 : 0), 0);
		if (modules.some((m) => p.text.includes(m))) score += 2;
		if (q.toLowerCase().includes("acceptable solution") && p.kind === "acceptable") score += 4;
		if (/taste|odour|aesthetic/.test(q.toLowerCase()) && p.kind === "aesthetic") score += 4;
		return {
			p,
			score
		};
	}).filter((x) => x.score >= Math.max(2, Math.min(ts.length, 2) * 2)).sort((a, b) => b.score - a.score).slice(0, 5).map((x) => x.p);
