	const rows = prepared?.rows || [...turn.found.slice(0, 4).map((p, i) => ({
		topic: `Relevant passage ${i + 1}`,
		answer: excerpt(p, turn.query),
		reference: `${p.title} · p. ${p.page}`,
		url: p.url
	})), ...council ? [{
		topic: "Local council website",
		answer: `Confirm local notices and the operator for ${council.name} with the council.`,
		reference: `${council.name} · water page`,
		url: waterLinks[council.name] || council.url
	}] : []];
	return {
		id: crypto.randomUUID(),
		askedAt: (/* @__PURE__ */ new Date()).toISOString(),
		question: turn.q,
		searchQuery: turn.query,
		supply,
		summary: prepared?.summary || "Relevant passages and links found for this question. The saved text is a lead, not a compliance determination.",
		scope: prepared?.scope || note(turn.query, supply),
		rows
	};
